1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { lstatSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  isCompleteIdea,
10	  normalizeIdea,
11	  fieldRulesBrowserScript,
12	  type ContentErrorCode,
13	} from './idea-fields.ts';
14	
15	const PRODUCT: string = 'FeatureHarbor';
16	const RESOURCE: string = 'ideas';
17	const MAX_BODY_BYTES = 1_000_000;
18	// 严格 UTF-8 解码器：fatal 模式遇到非法字节直接抛错，而不是像 Buffer.toString('utf8')
19	// 那样把坏字节静默替换成“�”。请求正文与磁盘上的已有意见都先在完整的字节缓冲上通过它，
20	// 才允许进入 JSON 解析；分段送达在缓冲拼接后判断，合法多字节字符被拆到相邻段不算损坏。
21	const UTF8_DECODER = new TextDecoder('utf-8', { fatal: true });
22	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
23	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
24	  'title-empty': '标题去掉首尾空白后不能为空',
25	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
26	  'description-empty': '详细说明必须包含非空白内容',
27	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
28	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
29	};
30	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
31	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
32	a{color:#175b9c}
33	label{display:block;font-weight:600;margin-top:1rem}
34	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
35	textarea{resize:vertical}
36	.required{color:#b00020}
37	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
38	#error{color:#b00020;margin-top:.75rem}
39	#success{color:#1a7f37;margin-top:.75rem}
40	.idea{border-top:1px solid #ddd;padding:1rem 0}
41	.idea h3{margin:0 0 .5rem}
42	.view-link{display:inline-block;margin-top:.5rem}
43	.pre{white-space:pre-wrap}
44	time{color:#666;font-size:.9rem}
45	#search-form{margin:1rem 0}
46	#search-form input{max-width:20rem;margin-right:.5rem}
47	#search-form button{margin-top:.25rem;margin-right:.5rem}
48	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
49	<h2>提交产品意见</h2>
50	<form id="idea-form" novalidate>
51	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
52	<input id="f-title" name="title" required>
53	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
54	<textarea id="f-desc" name="description" rows="5" required></textarea>
55	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
56	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
57	<button type="submit">提交意见</button>
58	<p id="error" role="alert" hidden></p>
59	<p id="success" role="status" hidden></p>
60	</form>
61	<h2>意见列表</h2>
62	<form id="search-form" role="search" novalidate>
63	<label for="f-search">关键词搜索</label>
64	<input id="f-search" name="q" type="search" placeholder="搜索标题、详细说明或使用场景" autocomplete="off">
65	<button type="submit">搜索</button>
66	<button id="search-clear" type="button">清空</button>
67	</form>
68	<p id="empty" hidden>还没有意见记录。</p>
69	<div id="ideas"></div>
70	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
71	</main><script>
72	${fieldRulesBrowserScript}
73	const form = document.getElementById('idea-form');
74	const titleInput = document.getElementById('f-title');
75	const descInput = document.getElementById('f-desc');
76	const scenarioInput = document.getElementById('f-scenario');
77	const errorBox = document.getElementById('error');
78	const successBox = document.getElementById('success');
79	const emptyNote = document.getElementById('empty');
80	const list = document.getElementById('ideas');
81	const searchForm = document.getElementById('search-form');
82	const searchInput = document.getElementById('f-search');
83	const searchClear = document.getElementById('search-clear');
84	const EMPTY_TEXT = '还没有意见记录。';
85	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
86	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
87	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
88	let listState = 'loading';
89	// 已生效的搜索关键词：去掉首尾空白后的完整一段文字，空字符串表示不搜索。
90	// 只影响当前页面的可见结果，不发起请求、不改变已保存记录与接口返回。
91	let activeKeyword = '';
92	// 纯文字的大小写不敏感包含判断：关键词内部空格按原文参与比较，
93	// 不拆词；标点、尖括号与看起来像正则表达式的文字都按普通文字查找，
94	// 因此直接用 includes，不能走正则。
95	function ideaMatches(idea, keyword) {
96	  const needle = keyword.toLowerCase();
97	  return idea.title.toLowerCase().includes(needle)
98	    || idea.description.toLowerCase().includes(needle)
99	    || idea.scenario.toLowerCase().includes(needle);
100	}
101	function showError(message) {
102	  errorBox.textContent = message;
103	  errorBox.hidden = false;
104	  successBox.hidden = true;
105	}
106	function renderIdea(idea) {
107	  const item = document.createElement('article');
108	  item.className = 'idea';
109	  const heading = document.createElement('h3');
110	  heading.textContent = idea.title;
111	  const desc = document.createElement('p');
112	  desc.className = 'pre';
113	  desc.textContent = idea.description;
114	  item.append(heading, desc);
115	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
116	    const scenario = document.createElement('p');
117	    const label = document.createElement('strong');
118	    label.textContent = '使用场景：';
119	    const text = document.createElement('span');
120	    text.className = 'pre';
121	    text.textContent = idea.scenario;
122	    scenario.append(label, text);
123	    item.append(scenario);
124	  }
125	  const time = document.createElement('time');
126	  time.dateTime = idea.createdAt;
127	  const parsed = new Date(idea.createdAt);
128	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
129	  item.append(time);
130	  // 每条已保存意见都有独立查看入口（搜索过滤后的结果与本页新提交同样带入口）：
131	  // 链接只由该记录的标识 id 决定，与标题、说明文字无关；id 经 encodeURIComponent
132	  // 编码，历史标识里的中文、空格或网址特殊字符也能准确指向自己的记录。
133	  // 历史标题可能为空，但入口不依赖标题，空标题记录仍可打开。
134	  // 标识恰为“.”或“..”时不能放进路径段：浏览器在发送前会做路径归一化，
135	  // 即使把点写成 %2E 也一样被当作当前/上一级目录移除，/ideas/. 最终请求到
136	  // /ideas/ 或首页，无法到达查看页；查询字符串不做这种归一化，因此这两个标识
137	  // 改由 /ideas?id=<encodeURIComponent(id)> 携带。其余标识一律仍走路径形式，
138	  // 链接与旧地址逐字不变（文字“%2E”是另一个标识，编码为 %252E，不受影响）。
139	  const viewLink = document.createElement('a');
140	  viewLink.className = 'view-link';
141	  viewLink.href = idea.id === '.' || idea.id === '..'
142	    ? '/ideas?id=' + encodeURIComponent(idea.id)
143	    : '/ideas/' + encodeURIComponent(idea.id);
144	  viewLink.textContent = '查看这条意见';
145	  item.append(viewLink);
146	  return item;
147	}
148	let remoteIdeas = [];
149	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
150	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
151	const submittedIdeas = [];
152	function renderList() {
153	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
154	  const seen = new Set();
155	  const ordered = [];
156	  for (const entry of submittedIdeas) {
157	    const idea = entry.idea;
158	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
159	  }
160	  for (const idea of remoteIdeas) {
161	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
162	  }
163	  // 搜索只过滤当前页面的可见结果：沿用合并后的原有顺序，逐条判断、不去重不重排，
164	  // 同一条意见最多出现一次；匹配的意见仍按原文渲染（保留空白与换行），不删改内容。
165	  const visible = activeKeyword
166	    ? ordered.filter((idea) => ideaMatches(idea, activeKeyword))
167	    : ordered;
168	  list.replaceChildren(...visible.map(renderIdea));
169	  if (listState === 'failed') {
170	    // 加载失败优先显示现有的失败提示，不能把失败显示成搜索无结果
171	    emptyNote.textContent = LOAD_FAILED_TEXT;
172	    emptyNote.hidden = false;
173	  } else if (listState !== 'ready') {
174	    // 首次列表仍在加载，不能把等待误报成没有记录或没有匹配结果
175	    emptyNote.hidden = true;
176	  } else if (activeKeyword) {
177	    // 搜索已生效：完整列表是否为空决定提示措辞，已有意见但无匹配时明确提示未找到
178	    emptyNote.textContent = ordered.length === 0 ? EMPTY_TEXT : NOT_FOUND_TEXT;
179	    emptyNote.hidden = visible.length > 0;
180	  } else {
181	    emptyNote.textContent = EMPTY_TEXT;
182	    emptyNote.hidden = ordered.length > 0;
183	  }
184	}
185	// 一条意见记录是否完整，直接使用 idea-fields.ts 注入的同一份 isCompleteIdea：
186	// 与服务读取已有数据的判定逐字相同，列表加载与提交确认都调用它，不在页面另写第二份。
187	async function loadIdeas() {
188	  try {
189	    const res = await fetch('/api/ideas');
190	    if (!res.ok) throw new Error('load failed');
191	    const data = await res.json();
192	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都完整；
193	    // 顶层结构异常或任意一条记录不完整都属于整次加载失败，
194	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
195	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
196	      throw new Error('invalid ideas response');
197	    }
198	    if (!data.ideas.every(isCompleteIdea)) throw new Error('invalid idea record');
199	    remoteIdeas = data.ideas;
200	    listState = 'ready';
201	  } catch {
202	    listState = 'failed';
203	  }
204	  renderList();
205	}
206	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
207	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
208	let editVersion = 0;
209	for (const field of [titleInput, descInput, scenarioInput]) {
210	  field.addEventListener('input', () => { editVersion += 1; });
211	}
212	// 字段内容判定与接口共用同一份实现（FIELD_LIMITS、codePointCount、checkIdeaContent
213	// 由 idea-fields.ts 注入）；这里只把共用判定结果映射成本页原有的提示措辞与顺序。
214	function validate(title, description, scenario) {
215	  switch (checkIdeaContent(title, description, scenario)) {
216	    case 'title-empty': return '标题不能为空。';
217	    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
218	    case 'description-empty': return '详细说明不能为空。';
219	    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
220	    case 'scenario-too-long': return '使用场景最多 ' + FIELD_LIMITS.scenario + ' 个字符。';
221	    default: return null;
222	  }
223	}
224	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
225	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
226	let latestSubmitSeq = 0;
227	form.addEventListener('submit', async (event) => {
228	  event.preventDefault();
229	  const submitSeq = ++latestSubmitSeq;
230	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
231	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
232	  errorBox.hidden = true;
233	  successBox.hidden = true;
234	  const title = titleInput.value;
235	  const description = descInput.value;
236	  const scenario = scenarioInput.value;
237	  const submittedVersion = editVersion;
238	  const problem = validate(title, description, scenario);
239	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
240	  // 之后更早请求的返回不能掩盖它
241	  if (problem) { showError(problem); return; }
242	  let res;
243	  try {
244	    res = await fetch('/api/ideas', {
245	      method: 'POST',
246	      headers: { 'content-type': 'application/json' },
247	      body: JSON.stringify({ title, description, scenario })
248	    });
249	  } catch {
250	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
251	    return;
252	  }
253	  let data = null;
254	  try { data = await res.json(); } catch { data = null; }
255	  if (!res.ok) {
256	    if (submitSeq === latestSubmitSeq) {
257	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
258	    }
259	    return;
260	  }
261	  // 成功状态的响应同样必须记录完整：顶层是含 idea 的 JSON 对象，
262	  // 且 idea 本身通过 isCompleteIdea 校验（对象、非空 id、各字段均为字符串）。
263	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
264	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
265	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isCompleteIdea(data.idea);
266	  if (!saved) {
267	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
268	    return;
269	  }
270	  const idea = data.idea;
271	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
272	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
273	  if (editVersion === submittedVersion) form.reset();
274	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
275	  // 不能为了避免提示干扰而丢弃真实保存结果。
276	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
277	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
278	  const entry = { seq: submitSeq, idea };
279	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
280	  if (insertAt === -1) insertAt = submittedIdeas.length;
281	  submittedIdeas.splice(insertAt, 0, entry);
282	  renderList();
283	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
284	  // 或新一次提交的等待旁边再显示成功
285	  if (submitSeq === latestSubmitSeq) {
286	    successBox.textContent = '提交成功，你的意见已保存。';
287	    successBox.hidden = false;
288	  }
289	});
290	// 搜索只在本页过滤已合并的完整列表：提交搜索表单不发起任何请求、不提交意见，
291	// 也不清空或改写提交意见表单里的草稿；关键词去掉首尾空白后为空时恢复完整列表。
292	// 已生效后，迟到的首次列表与本页新确认保存的意见都会在 renderList 中继续按它过滤。
293	function applySearch() {
294	  activeKeyword = searchInput.value.trim();
295	  renderList();
296	}
297	searchForm.addEventListener('submit', (event) => {
298	  event.preventDefault();
299	  applySearch();
300	});
301	searchClear.addEventListener('click', () => {
302	  searchInput.value = '';
303	  activeKeyword = '';
304	  renderList();
305	});
306	loadIdeas();
307	</script></html>`;
308	const VIEW_PATH_PREFIX = '/ideas/';
309	// 查看入口的集合路径：标识恰为“.”或“..”时无法使用路径段（会被网址路径归一化
310	// 移除，写成 %2E 也一样），首页改把标识放在查询串 /ideas?id= 中，这里负责接收。
311	const VIEW_COLLECTION_PATH = '/ideas';
312	// 单条意见查看页只展示常规字段（标题、完整详细说明、非空白使用场景、提交时间），
313	// 记录携带的附加信息一律不在页面公开。与首页一样，历史内容不重新套用新提交的限制：
314	// 超限、空白标题/说明、换行、中文、表情、网页标记样文本与实体写法都按原文显示。
315	const VIEW_FIELD_LABELS = {
316	  scenario: '使用场景',
317	  createdAt: '提交时间',
318	} as const;
319	// 服务端渲染时把所有意见文字按普通文字转义进 HTML：尖括号、引号、& 逐字显示，
320	// 不解析成页面元素；实体写法（如 &lt;）转义后显示为 &amp;lt;，仍是普通文字而不会被解码。
321	function escapeHtml(text: string): string {
322	  return text
323	    .replaceAll('&', '&amp;')
324	    .replaceAll('<', '&lt;')
325	    .replaceAll('>', '&gt;')
326	    .replaceAll('"', '&quot;')
327	    .replaceAll("'", '&#39;');
328	}
329	type CompleteIdea = {
330	  id: string;
331	  title: string;
332	  description: string;
333	  scenario: string;
334	  createdAt: string;
335	};
336	function renderIdeaViewPage(idea: CompleteIdea): string {
337	  const scenarioBlock = idea.scenario.trim().length > 0
338	    ? `<p><strong>${VIEW_FIELD_LABELS.scenario}：</strong><span class="pre">${escapeHtml(idea.scenario)}</span></p>\n`
339	    : '';
340	  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>意见详情 · FeatureHarbor</title><style>
341	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
342	a{color:#175b9c}
343	.pre{white-space:pre-wrap}
344	time{color:#666;font-size:.9rem}
345	.back{display:inline-block;margin-bottom:1.5rem}
346	.idea-id{color:#666;font-size:.9rem;word-break:break-all}
347	</style><main><p><a class="back" href="/">&larr; 返回首页</a></p>
348	<article class="idea">
349	<h2>${escapeHtml(idea.title)}</h2>
350	<p class="pre">${escapeHtml(idea.description)}</p>
351	${scenarioBlock}<p><strong>${VIEW_FIELD_LABELS.createdAt}：</strong><time datetime="${escapeHtml(idea.createdAt)}">${escapeHtml(idea.createdAt)}</time></p>
352	<p class="idea-id">意见标识：${escapeHtml(idea.id)}</p>
353	</article>
354	</main></html>`;
355	}
356	function renderMessagePage(heading: string, message: string): string {
357	  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${heading} · FeatureHarbor</title><style>
358	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
359	a{color:#175b9c}
360	.back{display:inline-block;margin-bottom:1.5rem}
361	</style><main><p><a class="back" href="/">&larr; 返回首页</a></p>
362	<h2>${heading}</h2>
363	<p>${message}</p>
364	</main></html>`;
365	}
366	// GET /ideas/:id 与 GET /ideas?id=:id —— 只展示该条已保存意见的独立页面，链接可直接
367	// 分享、刷新后仍是同一条。以记录标识精确匹配（先 decodeURIComponent 还原原始字符，
368	// 中文、空格与特殊字符与存储的 id 逐字比较），标题与说明相同但 id 不同的记录各自打开
369	// 各自的页面。存储读取失败明确提示加载失败（500），不能冒充不存在；能读取但找不到该 id
370	// 才提示该意见不存在（404），不展示其他意见。
371	//
372	// 标识恰为“.”或“..”时不能作为路径段：浏览器与服务端的 WHATWG 网址解析都会做路径
373	// 归一化，把它们当作当前/上一级目录移除——即使编码成 %2E 也一样（%2E 在路径段里会先
374	// 解码再归一化），请求到不了这里。这两个标识由首页以 /ideas?id=<encoded> 的查询串形式
375	// 给出，查询串不做路径归一化；encodedId 无论是路径段还是查询值，都统一在这里解码。
376	function showIdeaView(res: ServerResponse, encodedId: string): void {
377	  let targetId: string;
378	  try {
379	    targetId = decodeURIComponent(encodedId);
380	  } catch {
381	    respond(res, 404, renderMessagePage('该意见不存在', '你查看的意见不存在，可能已被删除。'), { html: true });
382	    return;
383	  }
384	  let records: unknown[];
385	  try {
386	    records = readIdeas();
387	  } catch {
388	    respond(res, 500, renderMessagePage('意见加载失败', '意见数据暂时无法读取，请稍后刷新重试。'), { html: true });
389	    return;
390	  }
391	  // readIdeas 已保证每条记录结构完整，这里只按标识逐字精确匹配
392	  const match = records.find((record) => (record as CompleteIdea).id === targetId) as CompleteIdea | undefined;
393	  if (!match) {
394	    respond(res, 404, renderMessagePage('该意见不存在', '你查看的意见不存在，可能已被删除。'), { html: true });
395	    return;
396	  }
397	  respond(res, 200, renderIdeaViewPage(match), { html: true });
398	}
399	// 路径段形式：/ideas/<encoded-id>，剥掉统一前缀后交给共用的解码渲染逻辑。
400	function handleIdeaView(res: ServerResponse, rawPath: string): void {
401	  showIdeaView(res, rawPath.slice(VIEW_PATH_PREFIX.length));
402	}
403	// 从 /ideas?id=<encoded-id> 的原始查询串中取出标识值（仍是 percent-encoded）。
404	// 只识别 id：取第一个 id 参数；裸 id（没有“=”）或空值视为没有标识段（返回 null，
405	// 路由按 /ideas 无标识处理）；这里不解码，畸形百分号编码交给 decodeURIComponent 判错。
