407	  if (!search.startsWith('?')) return null;
408	  for (const pair of search.slice(1).split('&')) {
409	    const equals = pair.indexOf('=');
410	    if ((equals === -1 ? pair : pair.slice(0, equals)) !== 'id') continue;
411	    if (equals === -1) return null;
412	    const value = pair.slice(equals + 1);
413	    return value.length > 0 ? value : null;
414	  }
415	  return null;
416	}
417	const args: string[] = process.argv.slice(2);
418	const help: string = `FeatureHarbor - 产品意见与公开路线图
419	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
