421	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
422	Port 0 selects an available port.
423	`;
424	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
425	  process.stdout.write(help);
426	  process.exit(args.length === 0 ? 2 : 0);
427	}
428	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
429	let host: string = '127.0.0.1';
430	let port: number = 8080;
431	let dataDir: string = 'data';
432	while (args.length) {
433	  const flag = args.shift();
434	  const value = args.shift();
435	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
436	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
437	  }
438	  if (flag === '--host') host = value;
439	  else if (flag === '--port') {
440	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
