449	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
450	  const body = options.html ? String(value) : JSON.stringify(value);
451	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
452	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
453	  res.end(body);
454	}
455	// 已有意见的结构完整性直接使用 idea-fields.ts 的 isCompleteIdea，
456	// 与首页列表加载、提交结果确认共用同一份判定。
457	function readIdeas(): unknown[] {
458	  // 先拿到原始字节并用 fatal TextDecoder 严格解码，再交给 JSON.parse：
459	  // readFileSync(path, 'utf8') 内部走 Buffer.toString('utf8')，会把非法 UTF-8 字节
460	  // 静默替换成“�”。替换后的文字若仍能组成完整记录，列表就会正常返回；此后提交新意见
461	  // 还会把替换后的旧内容一并保存，原始字节就此被改写。因此这里绝不能按“文字里有没有
462	  // �”判断（用户主动写下的“�”是以合法 UTF-8 EF BF BD 编码的普通文字，必须照常读取），
463	  // 而要由保存内容的实际字节编码决定：单独的续字节、缺少后续字节的多字节字符、不符合
464	  // UTF-8 规则的编码，无论出现在标题、详细说明、使用场景还是其他位置，都让整份数据
465	  // 读取失败——不替换、不忽略、不只读取其中的正常片段。
466	  const raw = readFileSync(dataFile);
467	  let text: string;
468	  try {
469	    text = UTF8_DECODER.decode(raw);
470	  } catch {
471	    throw new Error('Invalid UTF-8 in ideas storage');
472	  }
473	  const records: unknown = JSON.parse(text);
474	  if (!Array.isArray(records)) throw new Error('Invalid record list');
475	  // 任意一条记录不完整，整份列表都视为读取失败：
476	  // 不跳过异常记录，也不只返回正常部分。只检查结构，不套用新提交的内容限制：
477	  // 标题首尾空白、正文与场景换行、任意时间字符串都按原样保留，不补字段或改写文字。
478	  if (!records.every(isCompleteIdea)) throw new Error('Invalid idea record');
479	  return records;
480	}
481	function saveIdeas(records: unknown[]): void {
482	  const tempFile = `${dataFile}.tmp`;
483	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
484	  try {
485	    renameSync(tempFile, dataFile);
486	  } catch (error) {
487	    // 临时内容已写入但替换正式文件失败：尽量删除本次写出的临时普通文件，
488	    // 不让未保存成功的内容留下可被误认成已保存数据的副本。
489	    // 清理只针对普通文件——临时路径若是目录等本就不是本次写出的形态，一律不动；
490	    // 清理本身失败（如权限限制）只放弃清理，不掩盖原有的保存失败。
491	    try {
492	      if (lstatSync(tempFile).isFile()) unlinkSync(tempFile);
493	    } catch {
494	      // 忽略清理异常：保存失败的结果不变
495	    }
496	    throw error;
497	  }
498	}
499	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
