501	  // 中文、表情按 UTF-8 编码后的字节数计入；这与字段按 Unicode 码点的上限是两回事。
502	  const declaredLength = Number(req.headers['content-length']);
503	  let tooLarge = Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES;
504	  const chunks: Buffer[] = [];
505	  let size = 0;
506	  // 超限后不能写出 400 就立即 req.destroy()：客户端可能还在发送，强断会让它只看到
