508	  // 等请求正常结束后再回复，客户端只要发完并保持连接等待，就能收到完整可解析的 400。
509	  // 超限后的字节不再缓存：绝不能拿已收到的前缀去解析，更不能截断后尝试保存。
510	  try {
511	    for await (const chunk of req as AsyncIterable<Buffer>) {
512	      size += chunk.length;
513	      if (tooLarge) continue;
514	      if (size > MAX_BODY_BYTES) {
515	        tooLarge = true;
516	        chunks.length = 0;
517	        continue;
518	      }
519	      chunks.push(chunk);
520	    }
521	  } catch {
