570	  const problem = checkIdeaContent(rawTitle, rawDescription, scenario);
571	  if (problem) {
572	    respond(res, 400, { error: CONTENT_ERROR_MESSAGES[problem] });
573	    return;
574	  }
575	  const { title, description } = normalizeIdea(rawTitle, rawDescription, scenario);
576	  const idea = {
577	    id: randomUUID(),
578	    title,
579	    description,
580	    scenario,
581	    createdAt: new Date().toISOString(),
582	  };
