// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
let latestSubmitSeq = 0;
form.addEventListener('submit', async (event) => {
