const VIEW_PATH_PREFIX = '/ideas/';
// 查看入口的集合路径：标识恰为“.”或“..”时无法使用路径段（会被网址路径归一化
// 移除，写成 %2E 也一样），首页改把标识放在查询串 /ideas?id= 中，这里负责接收。
const VIEW_COLLECTION_PATH = '/ideas';
// 单条意见查看页只展示常规字段（标题、完整详细说明、非空白使用场景、提交时间），
// 记录携带的附加信息一律不在页面公开。与首页一样，历史内容不重新套用新提交的限制：
// 超限、空白标题/说明、换行、中文、表情、网页标记样文本与实体写法都按原文显示。
const VIEW_FIELD_LABELS = {
  scenario: '使用场景',
  createdAt: '提交时间',
} as const;
// 服务端渲染时把所有意见文字按普通文字转义进 HTML：尖括号、引号、& 逐字显示，
// 不解析成页面元素；实体写法（如 &lt;）转义后显示为 &amp;lt;，仍是普通文字而不会被解码。
function escapeHtml(text: string): string {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}
type CompleteIdea = {
  id: string;
  title: string;
  description: string;
  scenario: string;
  createdAt: string;
};
function renderIdeaViewPage(idea: CompleteIdea): string {
