281	
282	    // 文字“%2E”“%2E%2E”仍是不同标识，继续走路径形式并显示各自的记录，
283	    // 不能因为点标识改用查询串而与“.”“..”混成一条
284	    const literalOne = await fetchView(server, '%2E');
