286	    const literalOneHtml = await literalOne.text();
287	    assert.ok(literalOneHtml.includes('意见标识：%2E'));
288	    assert.ok(literalOneHtml.includes('文字百分号二E'));
289	    assert.ok(!literalOneHtml.includes('意见标识：.'));
290	    const literalTwo = await fetchView(server, '%2E%2E');
291	    assert.equal(literalTwo.status, 200);
292	    const literalTwoHtml = await literalTwo.text();
293	    assert.ok(literalTwoHtml.includes('意见标识：%2E%2E'));
294	    assert.ok(!literalTwoHtml.includes('意见标识：..'));
295	
296	    // 查询串指向不存在的标识：404 明确提示不存在，不展示其他意见
297	    const missing = await fetchViewQuery(server, 'no-such-id');
298	    assert.equal(missing.status, 404);
299	    const missingHtml = await missing.text();
300	    assert.ok(missingHtml.includes('该意见不存在'));
301	    assert.ok(!missingHtml.includes('意见标识：.'));
302	    assertBackHome(missingHtml);
303	  } finally {
304	    await server.stop();
305	    rmSync(dir, { recursive: true, force: true });
306	  }
