30	interface El {
31	  tagName: string;
32	  className: string;
33	  hidden: boolean;
34	  value: string;
35	  href: string;
36	  dateTime: string;
37	  children: El[];
38	  text: string | null;
39	  textContent: string;
40	  // 警戒标记：页面一旦通过 innerHTML 渲染内容即为 true（纯文本展示不允许走 innerHTML）
41	  innerHTMLAssigned: boolean;
42	  listeners: Record<string, Array<(event: unknown) => unknown>>;
43	  append(...nodes: El[]): void;
44	  replaceChildren(...nodes: El[]): void;
45	  addEventListener(type: string, fn: (event: unknown) => unknown): void;
46	  reset(): void;
47	}
48	
49	function makeElement(tag: string): El {
50	  const node = {
51	    tagName: tag.toUpperCase(),
52	    className: '',
53	    hidden: false,
54	    value: '',
55	    href: '',
56	    dateTime: '',
57	    children: [],
58	    text: null as string | null,
59	    innerHTMLAssigned: false,
60	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
61	    append(...nodes: El[]): void {
62	      this.children.push(...nodes);
63	    },
64	    replaceChildren(...nodes: El[]): void {
65	      this.children = [...nodes];
66	    },
67	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
68	      (this.listeners[type] ??= []).push(fn);
69	    },
70	    reset(): void {},
71	  };
72	  Object.defineProperty(node, 'textContent', {
73	    get(this: any): string {
74	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
75	    },
76	    set(this: any, value: unknown): void {
77	      this.text = String(value);
78	    },
79	  });
80	  // innerHTML 只记录不解析：意见内容若改走 innerHTML 渲染，textContent 断言会失败，
81	  // innerHTMLAssigned 标记则给出更直接的原因
82	  Object.defineProperty(node, 'innerHTML', {
83	    get(): string {
84	      return '';
85	    },
86	    set(this: any, value: unknown): void {
87	      this.innerHTMLAssigned = true;
88	    },
89	  });
90	  return node as El;
91	}
92	
93	interface Gate {
94	  promise: Promise<unknown>;
95	  resolve: (value: unknown) => void;
96	  reject: (error: Error) => void;
97	}
98	
99	function gate(): Gate {
100	  let resolve!: (value: unknown) => void;
101	  let reject!: (error: Error) => void;
102	  const promise = new Promise<unknown>((res, rej) => {
103	    resolve = res;
104	    reject = rej;
105	  });
106	  return { promise, resolve, reject };
107	}
108	
109	function jsonResponse(status: number, body: unknown): any {
110	  return {
111	    ok: status >= 200 && status < 300,
112	    status,
113	    json: async () => body,
114	  };
115	}
116	
117	function brokenJsonResponse(status = 201): any {
118	  return {
119	    ok: status >= 200 && status < 300,
120	    status,
121	    json: async () => {
122	      throw new SyntaxError('响应体不是有效 JSON');
123	    },
124	  };
125	}
126	
127	const flush = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 0));
128	
129	let ideaSeq = 0;
130	function makeIdea(partial: Record<string, unknown> = {}): Record<string, unknown> {
131	  ideaSeq += 1;
132	  return {
133	    id: `id-${ideaSeq}`,
134	    title: `标题 ${ideaSeq}`,
135	    description: `详细说明 ${ideaSeq}`,
136	    scenario: '',
137	    createdAt: '2026-01-01T00:00:00.000Z',
138	    ...partial,
139	  };
140	}
