142	const SUCCESS_TEXT = '提交成功，你的意见已保存。';
143	const EMPTY_TEXT = '还没有意见记录。';
144	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
145	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
146	const NETWORK_ERROR_TEXT = '网络错误，提交未成功，请重试。';
147	const SUBMIT_FAILED_TEXT = '提交失败，请稍后重试。';
148	
149	class Harness {
150	  els: Record<string, El> = {};
151	  // 页面脚本通过 document.createElement 创建过的全部元素（按创建先后），
152	  // 用于断言渲染只产生纯文本结构，不为意见内容创建脚本、图片、链接、表单等元素
153	  created: El[] = [];
154	  gets: Gate[] = [];
155	  getsIssued = 0;
156	  posts: Gate[] = [];
157	  postsIssued = 0;
158	  postBodies: unknown[] = [];
159	
160	  constructor(script: string) {
161	    const byId: Map<string, El> = new Map();
162	    const register = (id: string, tag: string, hidden = false): El => {
163	      const node = makeElement(tag);
164	      node.hidden = hidden;
165	      byId.set(id, node);
166	      this.els[id] = node;
167	      return node;
168	    };
169	    const form = register('idea-form', 'form');
170	    const titleInput = register('f-title', 'input');
171	    const descInput = register('f-desc', 'textarea');
172	    const scenarioInput = register('f-scenario', 'textarea');
173	    register('search-form', 'form');
174	    register('f-search', 'input');
175	    register('search-clear', 'button');
176	    register('error', 'p', true);
177	    register('success', 'p', true);
178	    register('empty', 'p', true);
179	    register('ideas', 'div');
180	    form.reset = (): void => {
181	      titleInput.value = '';
182	      descInput.value = '';
183	      scenarioInput.value = '';
184	    };
185	    const documentMock = {
186	      getElementById: (id: string): El => byId.get(id)!,
187	      createElement: (tag: string): El => {
188	        const el = makeElement(tag);
189	        this.created.push(el);
190	        return el;
191	      },
192	    };
193	    const fetchMock = (url: unknown, init?: { method?: string; body?: unknown }): Promise<unknown> => {
194	      const method = init?.method ?? 'GET';
195	      const pending = gate();
196	      if (method === 'POST') {
197	        this.posts.push(pending);
198	        this.postsIssued += 1;
199	        this.postBodies.push(init?.body);
200	      } else {
201	        this.gets.push(pending);
202	        this.getsIssued += 1;
203	      }
204	      return pending.promise;
205	    };
206	    const context = vm.createContext({ console, document: documentMock, fetch: fetchMock });
207	    vm.runInContext(script, context, { filename: 'inline-page-script.js' });
208	  }
